def encode(message, key, shift, encode=True):
    key = sorted(LOWER, key=f"{key}{LOWER}".index)
    result = []
    for char in message:
        if char in key:
            i = key.index(char)
            char = key[(i + shift) % 26]
            shift = i + 1 if encode else -(key.index(char) + 1)
