def consecutive_sum(num):
    upper_limit = 1
    while True:
        if upper_limit * (upper_limit + 1) // 2 > num:
            break
        upper_limit += 1
    result = []
    for i in range(1, upper_limit):
        if i % 2 and not num % i:
            result.insert(0, 1)
        elif not i % 2 and num % i == i // 2:
            result.insert(0, 1)
    return sum(result)
