def isPrime(n):
    if n <= 1:
        return False
    for i in range(2,int(math.sqrt(n)+1)):
        if n % i == 0:
            return False
    return True

def step(g,m,n):
    if m >= n:
        return []
    else:
        for i in range(m,n+1-g):
            if isPrime(i) and isPrime(i+g):
                return[i+g,i]
