                elif len(self.trackerForLargest[currSum]) > self.largestSize[0]:
                    self.numGroups[0] = 1
                    self.largestSize[0] = len(self.trackerForLargest[currSum])

                self.memory[num] = self.numGroups[0]

            self.largest[0] = n

