def namelist(names):
    # Validate input type
    if not isinstance(names, list):
        raise TypeError("Input must be a list")

    # Handle empty list
    if not names:
        return ''

    # Validate each element in the list
    for i, name_dict in enumerate(names):
        # Check that each element is a dictionary
        if not isinstance(name_dict, dict):
            raise TypeError(f"Element at index {i} must be a dictionary")

        # Check that 'name' key exists
        if 'name' not in name_dict:
            raise KeyError(f"Dictionary at index {i} must contain a 'name' key")

        # Check that name value is a string
        if not isinstance(name_dict['name'], str):
            raise TypeError(f"'name' value at index {i} must be a string")

        # Check that name is not empty
        if not name_dict['name'].strip():
            raise ValueError(f"'name' value at index {i} cannot be empty")

    # Original logic with validated data
    if len(names) > 1:
        return '{} & {}'.format(', '.join(name['name'] for name in names[:-1]), 
                                names[-1]['name'])
    else:
        return names[0]['name']
