        for s in "1,2abc,3def,4ghi,5jkl,6mno,7pqrs,8tuv,9wxyz,*,0,#".split(",") 
        # For each character in the button group, assign its position (1-based index)
        # i represents how many times you need to press that button
        # Example: for "2abc", a=1, b=2, c=3
        for i, c in enumerate(s, start=1)
    }
    # For each character in the input string, look up its keystroke count
    # and sum all the values together to get the total number of keystrokes
    return sum(lookup[c] for c in s)
