def primes_a_p(lower_limit, upper_limit):
    return [
        [n + i * gap for i in range(6)]
        for n in range(lower_limit | 1, upper_limit, 2)
        for gap in range(30, (upper_limit - n) // 5 + 1, 30)
        if all(map(is_prime, [n + i * gap for i in range(6)]))
    ]
